package vn.rtr.aeris.native98;
import java.util.*;import java.nio.file.*;import java.io.*;import static vn.rtr.aeris.native98.Data97.*;
public final class Unified98Test{
 static Map<String,byte[]>v=new HashMap<>();static List<Object>checks=new ArrayList<>();static long n=1000;static String G="00000000-0000-4000-8000-000000000098";
 interface Try{void run()throws Exception;}static void ok(String s,boolean b){if(!b)throw new AssertionError(s);checks.add(m("name",s,"pass",true));}static void no(String s,Try r)throws Exception{try{r.run();throw new AssertionError("DID_NOT_REJECT:"+s);}catch(IOException|IllegalArgumentException|IllegalStateException e){ok(s,true);}}
 static UnifiedCore98 fresh()throws Exception{n=1000;UnifiedCore98 u=new UnifiedCore98(new byte[4][38],G);u.receive(v.get("baseline"),n);u.attach(n);return u;}
 static String actor(UnifiedCore98 u){return(String)u.payload.join("pilot-a",n).get("sid");}static long rev(UnifiedCore98 u){return((Number)u.payload.snapshot(n).get("revision")).longValue();}static void claim(UnifiedCore98 u,String sid){u.payload.act(sid,1,rev(u),G,"claim","front","",++n);}
 public static void main(String[]args)throws Exception{for(String l:Files.readAllLines(Paths.get(args[0]))){String[]p=l.split("\t");v.put(p[0],DirectTransport95.unhex(p[1]));}
 UnifiedCore98 u=fresh();ok("one generation shared by flight and payload",u.payload.snapshot(n).get("generation").equals(G));no("second attach cannot regrant",()->u.attach(n));String a=actor(u);claim(u,a);PayloadCore97.Tx t=u.payload.command(a,2,rev(u),G,"front","capture",0,0,++n);byte[]p=u.wire(t.bytes),f=u.wire(u.payload.heartbeatBytes(n));ok("shared wire sequence differs across producers",(p[4]&255)==0&&(f[4]&255)==1);ok("resequencing preserves body and exact original intent",Arrays.equals(Arrays.copyOfRange(p,10,p.length-2),Arrays.copyOfRange(t.bytes,10,t.bytes.length-2)));u.payloadApprove(t,n);no("duplicate payload attempt blocked",()->u.payloadApprove(t,n));u.close("TEST_LINK_LOSS");ok("common close revokes flight",!u.flight.grantActive(n));ok("common close removes every payload owner",((List<Map<String,Object>>)u.payloadState(n).get("payloads")).stream().allMatch(x->x.get("ownerSid")==null));ok("common close has no live station",((List<Map<String,Object>>)u.payloadState(n).get("stations")).stream().noneMatch(x->Boolean.TRUE.equals(x.get("alive"))));ok("pending remains unknown on common close",t.state.startsWith("UNKNOWN_"));no("no payload command after loss",()->u.payload.command(a,3,rev(u),G,"front","focus",55,0,n));no("no attach after common close",()->u.attach(n));no("no flight approval after common close",()->u.flightApprove(f,n));
 UnifiedCore98 x=fresh();String xa=actor(x);claim(x,xa);no("payload bytes cannot bypass flight target gate",()->x.flightApprove(x.payload.command(xa,2,rev(x),G,"front","capture",0,0,++n).bytes,n));ok("cross-domain rejection closes common core",x.closed());
 UnifiedCore98 d=fresh();String da=actor(d);claim(d,da);d.detach("EXPLICIT_PAYLOAD_ONLY");ok("payload-only detach leaves common session running",!d.closed()&&!d.attached());no("detached core cannot be attached again",()->d.attach(n));d.receive(v.get("pulse0"),2000);ok("flight still consumes RX after payload detach",!d.closed());
 UnifiedCore98 c=fresh();String ca=actor(c);claim(c,ca);byte[]bad=v.get("ackZoom").clone();bad[bad.length-1]^=1;no("RX CRC failure closes both consumers",()->c.receive(bad,++n));ok("CRC failure payload owners revoked",((List<Map<String,Object>>)c.payloadState(n).get("payloads")).stream().allMatch(q->q.get("ownerSid")==null));UnifiedCore98 stale=fresh();no("common stale closes session",()->stale.tick(4001));ok("stale no restore",stale.closed());UnifiedCore98 clock=fresh();no("clock regression closes common session",()->clock.tick(999));
 // The identical send primitive is used by actual native flight and payload writes.
 List<String>order=new ArrayList<>();NativeSend98.send((k,b)->order.add(k),b->order.add("SOCKET"),()->true,()->order.add("APPROVE"),p);ok("durable intent then current approval then single socket then durable completion",order.equals(Arrays.asList("TX_INTENT","APPROVE","SOCKET","TX_WRITTEN")));
 int[]writes={0};no("fsync failure cannot send",()->NativeSend98.send((k,b)->{throw new IOException("FSYNC");},b->writes[0]++,()->true,()->{},p));ok("zero wire writes after WAL failure",writes[0]==0);boolean[]fg={true};no("revocation during approval cannot send",()->NativeSend98.send((k,b)->{},b->writes[0]++,()->fg[0],()->fg[0]=false,p));ok("zero writes after foreground revocation",writes[0]==0);no("policy failure cannot send",()->NativeSend98.send((k,b)->{},b->writes[0]++,()->true,()->{throw new IOException("REVOKED");},p));ok("zero writes after approval revocation",writes[0]==0);no("partial socket failure never retries",()->NativeSend98.send((k,b)->{},b->{writes[0]++;throw new IOException("PARTIAL_UNKNOWN");},()->true,()->{},p));ok("exactly one partial write attempt",writes[0]==1);no("post-write durability failure remains unknown",()->NativeSend98.send((k,b)->{if(k.equals("TX_WRITTEN"))throw new IOException("POST_WRITE_FSYNC");},b->writes[0]++,()->true,()->{},p));ok("post-write failure does not duplicate wire",writes[0]==2);
 UnifiedCore98 armed=fresh();no("unrequested armed heartbeat closes both domains",()->armed.receive(v.get("armedHB"),++n));ok("unexpected armed closes session",armed.closed());UnifiedCore98 notPilot=fresh();String np=actor(notPilot);claim(notPilot,np);no("payload ownership cannot authorize aircraft ARM",()->notPilot.flightApprove(v.get("flightArm"),++n));ok("unauthorized ARM revokes common authority",notPilot.closed());
 // Generate 260 sequential frames, CRC revalidated by an independent upstream replay later.
 UnifiedCore98 wrap=fresh();List<String>wire=new ArrayList<>();for(int i=0;i<260;i++){byte[]b=wrap.wire(wrap.payload.heartbeatBytes(n));if((b[4]&255)!=i%256)throw new AssertionError("WIRE_SEQUENCE_WRAP");wire.add(DirectTransport95Hex.hex(b));}ok("shared wire sequence wraps correctly over 260 samples",wire.size()==260);Files.write(Paths.get(args[1]),wire);System.out.println(json(m("status","PASS","checks",checks.size(),"cases",checks,"scope","PURE_JAVA_SHARED_SESSION_SEND_BOUNDARY_NOT_ANDROID")));}
 static class DirectTransport95Hex{static String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x&255));return s.toString();}}
}
